  "github_com_webbuilder_server_internal_shipping.Method": {
    "type": "object",
    "properties": {
      "carrier": {
        "description": "Carrier makes this a CARRIER-BACKED method: a carriers.Registry provider\nid (\"ghn\", \"ghtk\") whose live quote prices the order instead of FeeCents.\n\"\" is a flat/zone method, exactly as before carriers existed. FeeCents and\nZoneFees still matter on a carrier method: they are the FALLBACK charged\nwhenever the carrier cannot answer (see rates.Quote) — never 0.",
        "type": "string"
      },
      "carrierService": {
        "description": "CarrierService is the carrier's own service id (carriers.ServiceOption);\n\"\" means the provider's DefaultService. Always \"\" when Carrier is \"\".",
        "type": "string"
      },
      "createdAt": {
        "type": "string"
      },
      "description": {
        "description": "Description is the reassurance beside the option (\"2-3 ngày làm việc\").\nFree-form and never matched on.",
        "type": "string"
      },
      "disabled": {
        "description": "Disabled keeps a method configured but unofferable.\n\nNEGATIVE, so the zero value is the enabled default. A positive `Active`\nwould mean every Method built by a literal — every fixture, every\nhand-constructed test double — silently described a switched-off method,\nwhich is the default-true bool trap the webbuilder-go-api skill records\nfrom site.SubdomainRedirect. Inverting costs nothing while the column is\nstill ours to choose.",
        "type": "boolean"
      },
      "feeCents": {
        "description": "FeeCents is what this option costs, in minor units.",
        "type": "integer"
      },
      "freeOverCents": {
        "description": "FreeOverCents waives the fee once the order's subtotal reaches it.\n\nZERO MEANS \"never free\", not \"always free\". That reading is the one a\nmerchant expects from an empty box, and it is also the safe direction to\nbe wrong in: the alternative would make every method that was never\nconfigured ship for nothing.",
        "type": "integer"
      },
      "id": {
        "type": "string"
      },
      "isDefault": {
        "description": "IsDefault marks the one method a shopper gets when they name none (or\nname one this ask cannot use). At most one per site: the stores clear it\non every other method when it is set here. Nothing reads it on the v1\nengine.",
        "type": "boolean"
      },
      "name": {
        "description": "Name is what the shopper reads AND the pairing key an order form's\nchosen option is matched against — see the package doc. Unique per site,\ncase-insensitively.",
        "type": "string"
      },
      "position": {
        "description": "Position is the merchant's arrangement; ties break on Name.",
        "type": "integer"
      },
      "priorityOverride": {
        "description": "PriorityOverride replaces the site's priority document for THIS method's\nrules; nil follows the site order.",
        "allOf": [
          {
            "$ref": "#/definitions/github_com_webbuilder_server_internal_shipping.Priority"
          }
        ]
      },
      "siteId": {
        "type": "string"
      },
      "updatedAt": {
        "type": "string"
      },
      "zoneFees": {
        "description": "ZoneFees prices this method PER ZONE, keyed by zone id — the map behind\nFeeForZone. A zone with no entry falls back to FeeCents, so a merchant\nwho prices one method for one zone still has a working checkout for\nevery other combination.\n\nA MAP ON THE ROW rather than a method×zone table, and that is a\nconsidered exception to the normalise-everything rule: these fees are\nnever queried, sorted or aggregated on their own — every read wants them\nalongside the method they belong to — so a join table would buy a query\nnobody makes and cost one on every checkout.",
        "type": "object",
        "additionalProperties": {
          "type": "integer",
          "format": "int64"
        }
      }
    }
  },
